-- 0001_baseline: the ten tables carried from SQLite schema 8, columns in SQLite's order (Phase 1.5b, spec section 7.1).
-- Schema-unqualified: the migrator runs it with search_path set to the target schema.
CREATE TABLE observations (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, asset_id text COLLATE "C" NOT NULL, metric_key text COLLATE "C" NOT NULL,
  observed_at timestamptz NOT NULL, period_days double precision, value double precision NOT NULL,
  source text COLLATE "C" NOT NULL CHECK (source IN ('onchain','api','manual')), source_detail text COLLATE "C",
  status text COLLATE "C" NOT NULL CHECK (status IN ('confirmed','provisional','rejected')), citation_url text COLLATE "C",
  quoted_text text COLLATE "C", fetched_at timestamptz NOT NULL,
  superseded_by bigint REFERENCES observations(id) DEFERRABLE INITIALLY IMMEDIATE);
CREATE INDEX idx_obs_lookup ON observations (asset_id, metric_key, observed_at);
CREATE INDEX idx_obs_metric_day ON observations (asset_id, metric_key, observed_at DESC) WHERE superseded_by IS NULL AND status <> 'rejected';
CREATE TABLE fetch_runs (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, asset_id text COLLATE "C" NOT NULL,
  started_at timestamptz NOT NULL, ended_at timestamptz NOT NULL, outcome text COLLATE "C" NOT NULL CHECK (outcome IN ('ok','partial','failed')),
  detail_json json NOT NULL);
CREATE INDEX idx_fetch_runs_asset ON fetch_runs (asset_id, id);
CREATE TABLE fetch_cursors (asset_id text COLLATE "C" NOT NULL, scan_key text COLLATE "C" NOT NULL, last_block bigint NOT NULL,
  last_day date NOT NULL, updated_at timestamptz NOT NULL, PRIMARY KEY (asset_id, scan_key));
CREATE TABLE anomalies (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, asset_id text COLLATE "C" NOT NULL,
  kind text COLLATE "C" NOT NULL CHECK (kind IN ('cross_check_mismatch','unlisted_sender','source_failure_streak','revenue_disclosure_stale','revenue_payment')),
  metric_key text COLLATE "C" NOT NULL, dedupe_key text COLLATE "C" NOT NULL, severity text COLLATE "C" NOT NULL CHECK (severity IN ('degrading','advisory')),
  status text COLLATE "C" NOT NULL CHECK (status IN ('open','resolved','acknowledged')), detail_json json NOT NULL,
  occurrences bigint NOT NULL DEFAULT 1, first_seen_at timestamptz NOT NULL, last_seen_at timestamptz NOT NULL,
  note text COLLATE "C", decided_at timestamptz, decided_by text COLLATE "C");
CREATE INDEX idx_anomalies_asset ON anomalies (asset_id, status);
CREATE UNIQUE INDEX idx_anomalies_one_open ON anomalies (asset_id, kind, metric_key, dedupe_key) WHERE status = 'open';
CREATE TABLE coverage (asset_id text COLLATE "C" PRIMARY KEY, persona text COLLATE "C" NOT NULL, assigned_at timestamptz NOT NULL);
CREATE TABLE agent_runs (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, asset_id text COLLATE "C" NOT NULL, persona text COLLATE "C" NOT NULL,
  run_type text COLLATE "C" NOT NULL CHECK (run_type IN ('weekly','triage','deep','bootstrap','disclosure')),
  trigger_kind text COLLATE "C" NOT NULL, trigger_detail_json json NOT NULL,
  outcome text COLLATE "C" NOT NULL CHECK (outcome IN ('running','completed','budget_exhausted','refused','no_journal','conflict','error')),
  dry_run smallint NOT NULL DEFAULT 0 CHECK (dry_run IN (0,1)), config_hash text COLLATE "C" NOT NULL, model text COLLATE "C" NOT NULL,
  started_at timestamptz NOT NULL, ended_at timestamptz, requests bigint NOT NULL DEFAULT 0, input_tokens bigint NOT NULL DEFAULT 0,
  cache_read_tokens bigint NOT NULL DEFAULT 0, cache_write_tokens bigint NOT NULL DEFAULT 0, output_tokens bigint NOT NULL DEFAULT 0,
  web_searches bigint NOT NULL DEFAULT 0, web_fetches bigint NOT NULL DEFAULT 0, error text COLLATE "C", summary_json json);
CREATE INDEX idx_agent_runs_asset ON agent_runs (asset_id, id);
CREATE TABLE agent_transcripts (run_id bigint PRIMARY KEY REFERENCES agent_runs(id), messages_json json NOT NULL);
CREATE TABLE proposals (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, asset_id text COLLATE "C" NOT NULL, persona text COLLATE "C" NOT NULL,
  agent_run_id bigint REFERENCES agent_runs(id),
  kind text COLLATE "C" NOT NULL CHECK (kind IN ('config','acknowledge_anomaly','withdraw_acknowledgement','confirm_observation','reject_observation','observation')),
  change_json json NOT NULL, filed_against_json json NOT NULL, rationale text COLLATE "C" NOT NULL, evidence_json json NOT NULL, effect_json json,
  status text COLLATE "C" NOT NULL CHECK (status IN ('pending','approved','rejected')), created_at timestamptz NOT NULL, decided_at timestamptz,
  decision_note text COLLATE "C", citations_json json);
CREATE INDEX idx_proposals_asset ON proposals (asset_id, status);
CREATE TABLE journal (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, asset_id text COLLATE "C" NOT NULL, persona text COLLATE "C" NOT NULL,
  agent_run_id bigint REFERENCES agent_runs(id), created_at timestamptz NOT NULL, thesis text COLLATE "C" NOT NULL,
  open_questions_json json NOT NULL, summary text COLLATE "C" NOT NULL, catalysts_json json);
CREATE INDEX idx_journal_asset ON journal (asset_id, id);
CREATE TABLE documents (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, asset_id text COLLATE "C" NOT NULL,
  kind text COLLATE "C" NOT NULL CHECK (kind IN ('machine_transcript','transcript','post','filing','article')),
  source_url text COLLATE "C" NOT NULL, source_id text COLLATE "C", title text COLLATE "C", published_at text COLLATE "C",
  added_at timestamptz NOT NULL, sha256 text COLLATE "C" NOT NULL, bytes bigint NOT NULL, text text COLLATE "C" NOT NULL,
  meta_json json NOT NULL DEFAULT '{}');
CREATE UNIQUE INDEX idx_documents_hash ON documents (asset_id, sha256);
CREATE INDEX idx_documents_asset ON documents (asset_id, id);
